window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-120161c7fd661e4d"]={"versions": [{"id": "FIG-120161c7fd661e4d", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Supervised Entities und Checkpoints im Rahmen des Platform Health Management (PHM) der AUTOSAR Adaptive Platform (TPS Manifest Specification). Dargestellt ist die metamodellbasierte Schnittstellendefinition für die Überwachung von Software-Entitäten inklusive Generalisierungshierarchie und Kompositionsbeziehung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>PortInterface</strong>: Abstrakte Metaklasse / Wurzelelement mit den Stereotypen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><strong>PlatformHealthManagementInterface</strong>: Spezialisierung von <code>PortInterface</code> über Generalisierung (nicht-ausgefüllte Pfeilspitze).\n</li><li><strong>PhmSupervisedEntityInterface</strong>: Spezialisierung von <code>PlatformHealthManagementInterface</code> über Generalisierung; besitzt das Attribut <code>+ supervisedEntityId: PositiveInteger</code>.\n</li><li><strong>PhmCheckpoint</strong>: Mit Stereotyp <code>«AtpFeature»</code> versehenes Element zur Repräsentation einzelner Kontrollpunkte; besitzt das Attribut <code>+ checkpointId: PositiveInteger</code>.\n</li><li><strong>Beziehung</strong>: Komposition von <code>PhmSupervisedEntityInterface</code> zu <code>PhmCheckpoint</code> mit der Rollenbezeichnung <code>+checkpoint</code> und der Kardinalität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzdarstellung. Die Modellierung legt fest, dass eine überwachte Entität (<code>PhmSupervisedEntityInterface</code>) null bis beliebig viele Checkpoints instanziieren und besitzen kann, die zur Laufzeit von PHM zur Überwachung (Alive-, Deadline- oder Logical Supervision) herangezogen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung des AUTOSAR-Metamodells für Manifest-Beschreibungen von PHM-Schnittstellen. Eine <code>PhmSupervisedEntityInterface</code> muss eine eindeutige <code>supervisedEntityId</code> vom Typ <code>PositiveInteger</code> besitzen. Jeder zugeordnete <code>PhmCheckpoint</code> muss eine eindeutige <code>checkpointId</code> (<code>PositiveInteger</code>) aufweisen und ist existenzabhängig an das übergeordnete Interface gebunden.</p>"}, {"id": "FIG-ae8c61e11c30ef32", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Supervised Entities und Checkpoints im Rahmen des Platform Health Management (PHM) der AUTOSAR Adaptive Platform (TPS Manifest Specification). Dargestellt ist die metamodellbasierte Schnittstellendefinition für die Überwachung von Software-Entitäten inklusive Generalisierungshierarchie und Kompositionsbeziehung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>PortInterface</strong>: Abstrakte Metaklasse / Wurzelelement mit den Stereotypen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><strong>PlatformHealthManagementInterface</strong>: Spezialisierung von <code>PortInterface</code> über Generalisierung (nicht-ausgefüllte Pfeilspitze).\n</li><li><strong>PhmSupervisedEntityInterface</strong>: Spezialisierung von <code>PlatformHealthManagementInterface</code> über Generalisierung; besitzt das Attribut <code>+ supervisedEntityId: PositiveInteger</code>.\n</li><li><strong>PhmCheckpoint</strong>: Mit Stereotyp <code>«AtpFeature»</code> versehenes Element zur Repräsentation einzelner Kontrollpunkte; besitzt das Attribut <code>+ checkpointId: PositiveInteger</code>.\n</li><li><strong>Beziehung</strong>: Komposition von <code>PhmSupervisedEntityInterface</code> zu <code>PhmCheckpoint</code> mit der Rollenbezeichnung <code>+checkpoint</code> und der Kardinalität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzdarstellung. Die Modellierung legt fest, dass eine überwachte Entität (<code>PhmSupervisedEntityInterface</code>) null bis beliebig viele Checkpoints instanziieren und besitzen kann, die zur Laufzeit von PHM zur Überwachung (Alive-, Deadline- oder Logical Supervision) herangezogen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung des AUTOSAR-Metamodells für Manifest-Beschreibungen von PHM-Schnittstellen. Eine <code>PhmSupervisedEntityInterface</code> muss eine eindeutige <code>supervisedEntityId</code> vom Typ <code>PositiveInteger</code> besitzen. Jeder zugeordnete <code>PhmCheckpoint</code> muss eine eindeutige <code>checkpointId</code> (<code>PositiveInteger</code>) aufweisen und ist existenzabhängig an das übergeordnete Interface gebunden.</p>"}, {"id": "FIG-8b3e987e51328937", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Supervised Entities und Checkpoints im Rahmen des Platform Health Management (PHM) der AUTOSAR Adaptive Platform (TPS Manifest Specification). Dargestellt ist die metamodellbasierte Schnittstellendefinition für die Überwachung von Software-Entitäten inklusive Generalisierungshierarchie und Kompositionsbeziehung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>PortInterface</strong>: Abstrakte Metaklasse mit den Stereotypen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><strong>PlatformHealthManagementInterface</strong>: Spezialisierung von <code>PortInterface</code> über Generalisierung.\n</li><li><strong>PhmSupervisedEntityInterface</strong>: Spezialisierung von <code>PlatformHealthManagementInterface</code> mit dem Stereotyp <code>«AtpFeature»</code>; besitzt kein eigenes Attributfach mehr.\n</li><li><strong>PhmCheckpoint</strong>: Trägt den Stereotyp <code>«AtpFeature»</code> und besitzt das Attribut <code>+ checkpointId: PositiveInteger</code>.\n</li><li><strong>Beziehung</strong>: Komposition von <code>PhmSupervisedEntityInterface</code> zu <code>PhmCheckpoint</code> mit Rollenbezeichnung <code>+checkpoint</code> und Kardinalität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzdarstellung. Die Modellierung legt fest, dass eine überwachte Entität (<code>PhmSupervisedEntityInterface</code>) null bis beliebig viele Checkpoints instanziieren und besitzen kann, die zur Laufzeit von PHM zur Überwachung (Alive-, Deadline- oder Logical Supervision) herangezogen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für PHM-Manifeste. Die Identifikation der Supervised Entity erfolgt nicht mehr über ein explizites Attribut <code>supervisedEntityId</code> an <code>PhmSupervisedEntityInterface</code>, sondern über den Modellkontext bzw. Identifikatoren der Basisklassen. Für <code>PhmCheckpoint</code> ist weiterhin zwingend eine <code>checkpointId</code> als <code>PositiveInteger</code> vorgeschrieben.</p>"}, {"id": "FIG-d978b76c2d9dadd8", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Supervised Entities und Checkpoints im Rahmen des Platform Health Management (PHM) der AUTOSAR Adaptive Platform (TPS Manifest Specification). Dargestellt ist die metamodellbasierte Schnittstellendefinition für die Überwachung von Software-Entitäten inklusive Generalisierungshierarchie und Kompositionsbeziehung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>PortInterface</strong>: Abstrakte Metaklasse mit den Stereotypen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><strong>PlatformHealthManagementInterface</strong>: Spezialisierung von <code>PortInterface</code> über Generalisierung.\n</li><li><strong>PhmSupervisedEntityInterface</strong>: Spezialisierung von <code>PlatformHealthManagementInterface</code> mit dem Stereotyp <code>«AtpFeature»</code>; besitzt kein eigenes Attributfach mehr.\n</li><li><strong>PhmCheckpoint</strong>: Trägt den Stereotyp <code>«AtpFeature»</code> und besitzt das Attribut <code>+ checkpointId: PositiveInteger</code>.\n</li><li><strong>Beziehung</strong>: Komposition von <code>PhmSupervisedEntityInterface</code> zu <code>PhmCheckpoint</code> mit Rollenbezeichnung <code>+checkpoint</code> und Kardinalität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzdarstellung. Die Modellierung legt fest, dass eine überwachte Entität (<code>PhmSupervisedEntityInterface</code>) null bis beliebig viele Checkpoints instanziieren und besitzen kann, die zur Laufzeit von PHM zur Überwachung (Alive-, Deadline- oder Logical Supervision) herangezogen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für PHM-Manifeste. Die Identifikation der Supervised Entity erfolgt nicht mehr über ein explizites Attribut <code>supervisedEntityId</code> an <code>PhmSupervisedEntityInterface</code>, sondern über den Modellkontext bzw. Identifikatoren der Basisklassen. Für <code>PhmCheckpoint</code> ist weiterhin zwingend eine <code>checkpointId</code> als <code>PositiveInteger</code> vorgeschrieben.</p>"}, {"id": "FIG-cfcedb51cb765126", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Supervised Entities und Checkpoints im Rahmen des Platform Health Management (PHM) der AUTOSAR Adaptive Platform (TPS Manifest Specification). Dargestellt ist die metamodellbasierte Schnittstellendefinition für die Überwachung von Software-Entitäten inklusive Generalisierungshierarchie und Kompositionsbeziehung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>PortInterface</strong>: Abstrakte Metaklasse mit den Stereotypen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><strong>PlatformHealthManagementInterface</strong>: Spezialisierung von <code>PortInterface</code> über Generalisierung.\n</li><li><strong>PhmSupervisedEntityInterface</strong>: Spezialisierung von <code>PlatformHealthManagementInterface</code> mit dem Stereotyp <code>«AtpFeature»</code>; besitzt kein eigenes Attributfach mehr.\n</li><li><strong>PhmCheckpoint</strong>: Trägt den Stereotyp <code>«AtpFeature»</code> und besitzt das Attribut <code>+ checkpointId: PositiveInteger</code>.\n</li><li><strong>Beziehung</strong>: Komposition von <code>PhmSupervisedEntityInterface</code> zu <code>PhmCheckpoint</code> mit Rollenbezeichnung <code>+checkpoint</code> und Kardinalität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzdarstellung. Die Modellierung legt fest, dass eine überwachte Entität (<code>PhmSupervisedEntityInterface</code>) null bis beliebig viele Checkpoints instanziieren und besitzen kann, die zur Laufzeit von PHM zur Überwachung (Alive-, Deadline- oder Logical Supervision) herangezogen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für PHM-Manifeste. Die Identifikation der Supervised Entity erfolgt nicht mehr über ein explizites Attribut <code>supervisedEntityId</code> an <code>PhmSupervisedEntityInterface</code>, sondern über den Modellkontext bzw. Identifikatoren der Basisklassen. Für <code>PhmCheckpoint</code> ist weiterhin zwingend eine <code>checkpointId</code> als <code>PositiveInteger</code> vorgeschrieben.</p>"}, {"id": "FIG-1dbe556e8fb74adb", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition der Beziehung zwischen <code>PhmSupervisedEntityInterface</code> und <code>PhmCheckpoint</code> im Kontext des Platform Health Management der AUTOSAR Adaptive Platform (TPS Manifest Specification). Der Fokus liegt kompakt auf der Kompositionsbeziehung der Schnittstelle zu ihren Checkpoints.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>PhmSupervisedEntityInterface</strong>: Schnittstellenklasse unter dem Namensraum bzw. Stereotyp <code>PlatformHealthManagementInterface</code> ohne eigenes Attributfach.\n</li><li><strong>PhmCheckpoint</strong>: Klasse mit dem Stereotyp <code>«AtpFeature»</code>; besitzt das optionale Attribut <code>+ checkpointId: PositiveInteger [0..1]</code>.\n</li><li><strong>Beziehung</strong>: Komposition von <code>PhmSupervisedEntityInterface</code> zu <code>PhmCheckpoint</code> mit der Rollenbezeichnung <code>+checkpoint</code> und der Kardinalität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzdarstellung. Die Modellierung legt fest, dass eine überwachte Entität (<code>PhmSupervisedEntityInterface</code>) null bis beliebig viele Checkpoints instanziieren und besitzen kann, die zur Laufzeit von PHM zur Überwachung (Alive-, Deadline- oder Logical Supervision) herangezogen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der Checkpoint-Modellierung. Checkpoints werden über die Komposition <code>+checkpoint</code> mit Multiplizität <code>0..*</code> eingebunden. Das Attribut <code>checkpointId</code> an <code>PhmCheckpoint</code> ist optional mit Multiplizität <code>[0..1]</code> definiert, sodass Checkpoint-IDs modellseitig weggelassen oder implizit vergeben werden können.</p>"}, {"id": "FIG-e14edc2c0fc71d17", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition der Beziehung zwischen <code>PhmSupervisedEntityInterface</code> und <code>PhmCheckpoint</code> im Kontext des Platform Health Management der AUTOSAR Adaptive Platform (TPS Manifest Specification). Der Fokus liegt kompakt auf der Kompositionsbeziehung der Schnittstelle zu ihren Checkpoints.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>PhmSupervisedEntityInterface</strong>: Schnittstellenklasse unter dem Namensraum bzw. Stereotyp <code>PlatformHealthManagementInterface</code> ohne eigenes Attributfach.\n</li><li><strong>PhmCheckpoint</strong>: Klasse mit dem Stereotyp <code>«AtpFeature»</code>; besitzt das optionale Attribut <code>+ checkpointId: PositiveInteger [0..1]</code>.\n</li><li><strong>Beziehung</strong>: Komposition von <code>PhmSupervisedEntityInterface</code> zu <code>PhmCheckpoint</code> mit der Rollenbezeichnung <code>+checkpoint</code> und der Kardinalität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzdarstellung. Die Modellierung legt fest, dass eine überwachte Entität (<code>PhmSupervisedEntityInterface</code>) null bis beliebig viele Checkpoints instanziieren und besitzen kann, die zur Laufzeit von PHM zur Überwachung (Alive-, Deadline- oder Logical Supervision) herangezogen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der Checkpoint-Modellierung. Checkpoints werden über die Komposition <code>+checkpoint</code> mit Multiplizität <code>0..*</code> eingebunden. Das Attribut <code>checkpointId</code> an <code>PhmCheckpoint</code> ist optional mit Multiplizität <code>[0..1]</code> definiert, sodass Checkpoint-IDs modellseitig weggelassen oder implizit vergeben werden können.</p>"}, {"id": "FIG-a97fd648c3814fab", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von <code>PhmSupervisedEntityInterface</code> und <code>PhmCheckpoint</code> sowie deren Einbettung in die Vererbungshierarchie der AUTOSAR-Port-Schnittstellen im Kontext des Platform Health Management der AUTOSAR Adaptive Platform (TPS Manifest Specification).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>PortInterface</strong>: Übergeordnete Schnittstellenklasse mit den Stereotypen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><strong>PlatformHealthManagementInterface</strong>: Abstrakte Zwischenklasse (kursiv dargestellt), die per Generalisierung von <code>PortInterface</code> erbt.\n</li><li><strong>PhmSupervisedEntityInterface</strong>: Konkrete Schnittstellenklasse für überwachte Entitäten, die per Generalisierung von <code>PlatformHealthManagementInterface</code> erbt.\n</li><li><strong>PhmCheckpoint</strong>: Klasse mit dem Stereotyp <code>«AtpFeature»</code>; besitzt das optionale Attribut <code>+ checkpointId: PositiveInteger [0..1]</code>.\n</li><li><strong>Beziehung</strong>: Komposition von <code>PhmSupervisedEntityInterface</code> zu <code>PhmCheckpoint</code> mit der Rollenbezeichnung <code>+checkpoint</code> und der Multiplizität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzdarstellung. Die Modellierung legt fest, dass eine überwachte Entität (<code>PhmSupervisedEntityInterface</code>) null bis beliebig viele Checkpoints instanziieren und besitzen kann, die zur Laufzeit von PHM zur Überwachung (Alive-, Deadline- oder Logical Supervision) herangezogen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der Checkpoint-Modellierung und Schnittstellenhierarchie. <code>PhmSupervisedEntityInterface</code> ist über <code>PlatformHealthManagementInterface</code> als spezialisiertes <code>PortInterface</code> und damit als <code>ARElement</code>, <code>AtpBlueprint</code> sowie <code>AtpType</code> typisiert. Checkpoints werden über die Komposition <code>+checkpoint</code> mit Multiplizität <code>0..*</code> eingebunden. Das Attribut <code>checkpointId</code> an <code>PhmCheckpoint</code> ist optional mit Multiplizität <code>[0..1]</code> definiert, sodass Checkpoint-IDs modellseitig weggelassen oder implizit vergeben werden können.</p>"}, {"id": "FIG-a277a43bdacd44c9", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von <code>PhmSupervisedEntityInterface</code> und <code>PhmCheckpoint</code> sowie deren Einbettung in die Vererbungshierarchie der AUTOSAR-Port-Schnittstellen im Kontext des Platform Health Management der AUTOSAR Adaptive Platform (TPS Manifest Specification).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>PortInterface</strong>: Übergeordnete Schnittstellenklasse mit den Stereotypen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><strong>PlatformHealthManagementInterface</strong>: Abstrakte Zwischenklasse (kursiv dargestellt), die per Generalisierung von <code>PortInterface</code> erbt.\n</li><li><strong>PhmSupervisedEntityInterface</strong>: Konkrete Schnittstellenklasse für überwachte Entitäten, die per Generalisierung von <code>PlatformHealthManagementInterface</code> erbt.\n</li><li><strong>PhmCheckpoint</strong>: Klasse mit dem Stereotyp <code>«AtpFeature»</code>; besitzt das optionale Attribut <code>+ checkpointId: PositiveInteger [0..1]</code>.\n</li><li><strong>Beziehung</strong>: Komposition von <code>PhmSupervisedEntityInterface</code> zu <code>PhmCheckpoint</code> mit der Rollenbezeichnung <code>+checkpoint</code> und der Multiplizität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzdarstellung. Die Modellierung legt fest, dass eine überwachte Entität (<code>PhmSupervisedEntityInterface</code>) null bis beliebig viele Checkpoints instanziieren und besitzen kann, die zur Laufzeit von PHM zur Überwachung (Alive-, Deadline- oder Logical Supervision) herangezogen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der Checkpoint-Modellierung und Schnittstellenhierarchie. <code>PhmSupervisedEntityInterface</code> ist über <code>PlatformHealthManagementInterface</code> als spezialisiertes <code>PortInterface</code> und damit als <code>ARElement</code>, <code>AtpBlueprint</code> sowie <code>AtpType</code> typisiert. Checkpoints werden über die Komposition <code>+checkpoint</code> mit Multiplizität <code>0..*</code> eingebunden. Das Attribut <code>checkpointId</code> an <code>PhmCheckpoint</code> ist optional mit Multiplizität <code>[0..1]</code> definiert, sodass Checkpoint-IDs modellseitig weggelassen oder implizit vergeben werden können.</p>"}], "trans": [{"from": "FIG-120161c7fd661e4d", "to": "FIG-ae8c61e11c30ef32", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Attribut <code>PhmSupervisedEntityInterface.supervisedEntityId</code>: Formatierung von <code>:PositiveInteger</code> zu <code>: PositiveInteger</code> geändert (Leerzeichen nach Doppelpunkt).\n</li><li>Attribut <code>PhmCheckpoint.checkpointId</code>: Formatierung von <code>:PositiveInteger</code> zu <code>: PositiveInteger</code> geändert (Leerzeichen nach Doppelpunkt).\n</li></ul>"}, {"from": "FIG-ae8c61e11c30ef32", "to": "FIG-8b3e987e51328937", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Klasse <code>PhmSupervisedEntityInterface</code>: Attribut <code>+ supervisedEntityId: PositiveInteger</code> sowie das zugehörige Attributfach wurden entfernt.\n</li><li>Stereotyp <code>«AtpFeature»</code>: Oberhalb von <code>PhmSupervisedEntityInterface</code> neu als Stereotyp deklariert (im Namensfach).\n</li></ul>"}, {"from": "FIG-8b3e987e51328937", "to": "FIG-d978b76c2d9dadd8", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d978b76c2d9dadd8", "to": "FIG-cfcedb51cb765126", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cfcedb51cb765126", "to": "FIG-1dbe556e8fb74adb", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Klassen <code>PortInterface</code> und <code>PlatformHealthManagementInterface</code>: Die separaten Klassenboxen der Vererbungshierarchie sowie die Generalisierungspfeile wurden entfernt; <code>PlatformHealthManagementInterface</code> wird stattdessen als übergeordneter Stereotyp bzw. Namensraum direkt im Header von <code>PhmSupervisedEntityInterface</code> geführt.\n</li><li>Klasse <code>PhmSupervisedEntityInterface</code>: Der Stereotyp <code>«AtpFeature»</code> entfällt an dieser Klasse.\n</li><li>Attribut <code>PhmCheckpoint.checkpointId</code>: Multiplizität <code>[0..1]</code> hinzugefügt (<code>+ checkpointId: PositiveInteger [0..1]</code>).\n</li></ul>"}, {"from": "FIG-1dbe556e8fb74adb", "to": "FIG-e14edc2c0fc71d17", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e14edc2c0fc71d17", "to": "FIG-a97fd648c3814fab", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>PhmSupervisedEntityInterface</code>: Vererbungshierarchie explizit modelliert; erbt über Generalisierung von der abstrakten Klasse <code>PlatformHealthManagementInterface</code>.\n</li><li><code>PlatformHealthManagementInterface</code>: Als eigene abstrakte Schnittstellenklasse dargestellt; erbt über Generalisierung von <code>PortInterface</code>.\n</li><li><code>PortInterface</code>: Als übergeordnete Klasse mit den Stereotypen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code> in die Vererbungshierarchie eingefügt.\n</li></ul>"}, {"from": "FIG-a97fd648c3814fab", "to": "FIG-a277a43bdacd44c9", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
